import * as T from './vendor/three.module.js';
import {createWeaponModel,WEAPON_MODELS} from './weapon-models.js';
import {ANIMAL_MOTION_CATALOG} from './animal-motion-catalog.js';
import {createAnimalPaint} from './animal-motion-paint.js';
import {createRedHatCap} from './red-hat-model.js';
import {LIGHT_ATLAS} from './horse-light-model.js';
import {createRoofMantle} from './roof-mantle.js';

import {createPaintedGrass} from './painted-grass.js';
const $=id=>document.getElementById(id),params=new URLSearchParams(location.search);
for(const p of ANIMAL_MOTION_CATALOG){const o=document.createElement('option');o.value=p.id;o.textContent=p.label;$('animal').append(o);}
for(const [id,p]of Object.entries(WEAPON_MODELS)){const o=document.createElement('option');o.value=id;o.textContent=p.label;$('weapon').append(o);}$('weapon').value='rifle';
let profile=ANIMAL_MOTION_CATALOG[0];
for(const id of ['animal','outfit','weapon','view','scale'])if([...$(id).options].some(o=>o.value===params.get(id)))$(id).value=params.get(id);
const renderer=new T.WebGLRenderer({canvas:$('scene'),antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(1);renderer.setSize(1400,850,false);renderer.setClearColor('#303b33');renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;
const scene=new T.Scene(),camera=new T.OrthographicCamera(),loader=new T.TextureLoader();scene.add(new T.HemisphereLight(0xfff1d3,0x778878,2));const sun=new T.DirectionalLight(0xffecd5,2.4);sun.position.set(-4,8,-5);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.normalBias=.012;Object.assign(sun.shadow.camera,{left:-6,right:6,top:6,bottom:-6});scene.add(sun);
const ground=new T.Mesh(new T.PlaneGeometry(24,24),createPaintedGrass());ground.rotation.x=-Math.PI/2;ground.position.y=-.01;ground.receiveShadow=true;scene.add(ground);
// Same two-unit wall height as the approved climb proof, with a plain roof.
const roofMaterial=new T.MeshStandardMaterial({color:0x969387,roughness:1}),roofGeometry=new T.BoxGeometry(3,2,4),roof=new T.Mesh(roofGeometry,roofMaterial);roof.position.set(1.5,1,0);roof.receiveShadow=roof.castShadow=true;scene.add(roof);const cliff={root:roof,dispose(){roofGeometry.dispose();roofMaterial.dispose();}};
const dots=new T.Group();scene.add(dots);const markers=Array.from({length:4},()=>{const m=new T.Mesh(new T.SphereGeometry(.025,10,8),new T.MeshBasicMaterial({color:0xf5e987,depthTest:false}));m.renderOrder=4;dots.add(m);return m;});
let worker,paint,cap,motion,selectedWeapon,loading=false,playing=false,last=0,progress=0;
function disposeActor(){if(!worker)return;scene.remove(worker.root);motion?.dispose();cap?.dispose();paint?.dispose();selectedWeapon?.dispose();selectedWeapon=null;worker.skeleton.dispose();worker.dispose();worker=paint=cap=motion=null;}
const texture=await loader.loadAsync(LIGHT_ATLAS);texture.colorSpace=T.SRGBColorSpace;
async function load(){if(loading)return;loading=true;playing=false;$('play').textContent='Play';window.roofMantleStudy.ready=false;const animal=$('animal').value;profile=ANIMAL_MOTION_CATALOG.find(p=>p.id===animal);const guideOption=$('outfit').querySelector('[value=blue-hawaiian]');guideOption.disabled=animal!=='donkey';if(guideOption.disabled&&$('outfit').value==='blue-hawaiian')$('outfit').value='normal';const outfit=$('outfit').value;const unarmed=profile.unarmed||outfit==='blue-hawaiian';$('weapon').disabled=unarmed;if(unarmed)$('weapon').value='hands';const weapon=$('weapon').value;try{disposeActor();const response=await fetch(profile.file);if(!response.ok)throw Error(profile.label+' mesh failed to load');worker=profile.create(await response.json(),texture);if(!profile.unarmed&&weapon!=='rifle'){selectedWeapon=createWeaponModel(weapon,texture);worker.equipWeapon(selectedWeapon);}paint=await createAnimalPaint(renderer,worker,profile,loader,outfit);for(const p of worker.parts){p.material=paint.material;p.castShadow=p.receiveShadow=true;}cap=outfit==='red-hats'?await createRedHatCap(renderer,worker,profile,loader):null;motion=profile.unarmed?(await import('./hen-roof-mantle.js')).createHenRoofMantle(worker,profile):createRoofMantle(worker,profile);$('phases').replaceChildren();for(const p of motion.phases){const b=document.createElement('button');b.textContent=p.label;b.onclick=()=>window.roofMantleStudy.seek((p.start+p.end)/(2*motion.duration));$('phases').append(b);}scene.add(worker.root);window.roofMantleStudy.ready=true;render();}catch(e){$('status').textContent=e.message;console.error(e);}finally{loading=false;if(outfit!==$('outfit').value||animal!==$('animal').value||weapon!==$('weapon').value)load();}}
function render(){if(!motion)return;const url=new URL(location.href);for(const id of ['animal','outfit','weapon','view','scale'])url.searchParams.set(id,$(id).value);if(url.href!==location.href)history.replaceState(null,'',url);const d=motion.apply(progress),scale={full:180,close:310,game:58}[$('scale').value],center=$('scale').value==='close'?new T.Vector3(d.root[0]+.15,d.root[1]+1,0):new T.Vector3(.4,1.85,0),view={three:[-1,.38,1.4],side:[0,.12,1],front:[1,.3,0],rear:[-1,.22,0]}[$('view').value];
for(const p of worker.parts)p.material=$('grey').checked?worker.grey:paint.material;camera.left=-700/scale;camera.right=700/scale;camera.top=425/scale;camera.bottom=-425/scale;camera.near=.01;camera.far=80;camera.position.copy(center).add(new T.Vector3(...view).multiplyScalar(8));camera.lookAt(center);camera.updateProjectionMatrix();dots.visible=$('contacts').checked;const c=d.contacts.filter(c=>c.point);markers.forEach((m,i)=>{m.visible=!!c[i];if(c[i]){m.position.fromArray(c[i].worldPoint||c[i].point);m.material.color.set(c[i].planted?0x9beb83:0xffb265);}});renderer.render(scene,camera);$('progress').value=progress;$('time').textContent=`${(progress*motion.duration).toFixed(2)} / ${motion.duration.toFixed(2)} s`;$('status').textContent=d.phase;Object.assign(window.roofMantleStudy,{worker,motion,result:d,profile});}
window.roofMantleStudy={ready:false,renderer,scene,camera,cliff,seek(p){playing=false;$('play').textContent='Play';progress=T.MathUtils.clamp(p,0,1);render();},render};
$('outfit').onchange=load;$('weapon').onchange=load;$('animal').onchange=()=>{progress=0;load();};for(const id of ['view','scale','grey','contacts'])$(id).oninput=render;$('progress').oninput=()=>window.roofMantleStudy.seek(+$('progress').value);$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'Pause':'Play';if(progress===1)progress=0;last=performance.now();};
document.addEventListener('visibilitychange',()=>{if(document.hidden){playing=false;$('play').textContent='Play';}});
let frame;function animate(now){if(playing&&motion){progress=Math.min(1,progress+Math.min(.1,(now-last)/1000)/motion.duration);render();if(progress===1){playing=false;$('play').textContent='Play';}}last=now;frame=requestAnimationFrame(animate);}frame=requestAnimationFrame(animate);addEventListener('pagehide',()=>{cancelAnimationFrame(frame);disposeActor();cliff.dispose();texture.dispose();ground.geometry.dispose();ground.material.dispose();markers.forEach(m=>{m.geometry.dispose();m.material.dispose();});renderer.dispose();},{once:true});load();
